        vector<int> dp(n, -1);
        dp[0] = 0;

        for (int i = 1; i < n; ++i) {
            for (int j = 0; j < i; ++j) {
                if (dp[j] != -1) {
                    long long diff = (long long)nums[i] - nums[j];
                    if (diff >= -target && diff <= target) {
                        dp[i] = max(dp[i], dp[j] + 1);
                    }
                }
            }
        }

        return dp[n - 1];
    }
};

